package main
import("context";"net/http";"net/http/httptest";"sync/atomic";"path/filepath";"os/exec";"testing";"github.com/generalbusiness-ai/gitseq/internal/app";"github.com/generalbusiness-ai/gitseq/internal/workroom")
func TestPlannerCurrentConnectorRouting(t *testing.T){
 for _,tc:=range []struct{name string;advertise bool;flag string;wantAppend bool;wantDials int32}{{"no_advertisement_default",false,"",true,0},{"advertised_default",true,"",true,0},{"advertised_local_sentinel",true,"-",false,0},{"explicit_resident_control",true,"url",false,1}}{
 t.Run(tc.name,func(t *testing.T){ctx:=context.Background();var dials atomic.Int32;srv:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){dials.Add(1);http.Error(w,"controlled resident refusal",503)}));defer srv.Close();repo:=filepath.Join(t.TempDir(),"repo");if out,err:=exec.Command("git","init","-q",repo).CombinedOutput();err!=nil{t.Fatalf("init: %v %s",err,out)}
 ws,seed,err:=app.Init(ctx,repo,"connector",1<<20);if err!=nil{t.Fatal(err)};if tc.advertise{withdraw,err:=ws.PublishResident(srv.URL);if err!=nil{t.Fatal(err)};defer withdraw()};actor,err:=loadObservationIdentity(ws,"connector");if err!=nil{t.Fatal(err)};req,err:=ws.BuildActRequest(ctx,actor.Private,actor.Name,app.Act{Verb:app.VerbState,Kind:workroom.KindAssert,Text:"isolated routing probe",RestsOn:[]string{seed.ID}});if err!=nil{t.Fatal(err)};before,err:=ws.Snapshot(ctx);if err!=nil{t.Fatal(err)};flag:=tc.flag;if flag=="url"{flag=srv.URL};id,gotErr:=submit(ctx,ws,flag,req);after,err:=ws.Snapshot(ctx);if err!=nil{t.Fatal(err)};changed:=before.Head!=after.Head
 if changed!=tc.wantAppend || (gotErr==nil)!=tc.wantAppend || dials.Load()!=tc.wantDials{t.Fatalf("append=%v err=%v dials=%d",changed,gotErr,dials.Load())};if tc.wantAppend && id==""{t.Fatal("no event")};t.Logf("advertised=%v flag=%q appended=%v dials=%d error=%v",tc.advertise,tc.flag,changed,dials.Load(),gotErr)
 })}
}
